import{_ as t,o as r,c as a,ae as o}from"./chunks/framework.vXWZTEWX.js";const u=JSON.parse('{"title":"ADR 023: Resilience and Testing Strategy 🧪","description":"","frontmatter":{},"headers":[],"relativePath":"adr/023-resilience-testing-strategy.md","filePath":"adr/023-resilience-testing-strategy.md"}'),n={name:"adr/023-resilience-testing-strategy.md"};function i(s,e,l,d,c,g){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-023-resilience-and-testing-strategy-🧪" tabindex="-1">ADR 023: Resilience and Testing Strategy 🧪 <a class="header-anchor" href="#adr-023-resilience-and-testing-strategy-🧪" aria-label="Permalink to &quot;ADR 023: Resilience and Testing Strategy 🧪&quot;">​</a></h1><p>Date: 2026-03-04</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>As the application moves towards production readiness (Phase 8), we need to ensure robustness against failures and verify the &quot;Happy Path&quot; end-to-end. Previously, error handling was inconsistent (mixed <code>res.status</code> and <code>next(err)</code>), and testing was limited to unit tests with strict 100% thresholds that blocked CI execution.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We have adopted a comprehensive <strong>Resilience &amp; Testing Strategy</strong> consisting of three pillars:</p><h3 id="_1-global-error-handling" tabindex="-1">1. Global Error Handling <a class="header-anchor" href="#_1-global-error-handling" aria-label="Permalink to &quot;1. Global Error Handling&quot;">​</a></h3><p>We standardized backend error handling by routing all errors through a centralized <code>globalErrorHandler</code> middleware.</p><ul><li><strong>Pattern</strong>: Controllers must catch errors and pass them to <code>next(error)</code> or throw <code>AppError</code> instances.</li><li><strong>Operational vs. Programmer Errors</strong>: <ul><li><code>AppError</code> (Operational): Anticipated errors (e.g., 400 Bad Request, 401 Unauthorized, 404 Not Found). These are returned to the client as JSON.</li><li><code>Error</code> (Programmer/Unexpected): Crashes, DB connection failures. These are logged to <strong>Sentry</strong> (if enabled) and returned as generic 500 errors to prevent info leaks.</li></ul></li><li><strong>Refactoring</strong>: Middleware (<code>authMiddleware</code>) and Controllers (<code>TenderController</code>, <code>AuthController</code>) were refactored to conform to this pattern.</li></ul><h3 id="_2-end-to-end-e2e-testing" tabindex="-1">2. End-to-End (E2E) Testing <a class="header-anchor" href="#_2-end-to-end-e2e-testing" aria-label="Permalink to &quot;2. End-to-End (E2E) Testing&quot;">​</a></h3><p>We introduced <strong>Playwright</strong> to verify critical user flows that unit tests cannot capture.</p><ul><li><strong>Scope</strong>: The &quot;Happy Path&quot; (Registration -&gt; Upload -&gt; Analysis).</li><li><strong>Environment</strong>: Tests run against the local development server (<code>npm run dev</code>).</li><li><strong>Mocking</strong>: External AI calls (<code>/api/tenders/analyze</code>) are mocked network-side to ensure determinism and cost-saving during test runs.</li><li><strong>Artifacts</strong>: Execution records videos (<code>.webm</code>) for visual verification.</li></ul><h3 id="_3-pragmatic-code-coverage" tabindex="-1">3. Pragmatic Code Coverage <a class="header-anchor" href="#_3-pragmatic-code-coverage" aria-label="Permalink to &quot;3. Pragmatic Code Coverage&quot;">​</a></h3><p>We adjusted <strong>Vitest</strong> coverage thresholds to balance quality with velocity.</p><ul><li><strong>Domain Layer</strong>: 100% -&gt; <strong>80%+</strong> (Strict logic validation).</li><li><strong>Global</strong>: 80% -&gt; <strong>60%</strong> (Baseline for CI/CD stability).</li><li><strong>Rationale</strong>: Strict 100% thresholds were causing false positives and blocking valid builds. 60% global coverage is a healthy baseline given the addition of E2E tests which cover integration paths.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li><strong>Observability</strong>: All 500 errors are now centralized and can be instrumented (Sentry).</li><li><strong>Confidence</strong>: E2E tests prove the system works from a user perspective.</li><li><strong>Stability</strong>: Lowered strict thresholds prevent CI from breaking on minor changes, while E2E tests ensure actual functionality.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li><strong>Complexity</strong>: New toolchain (Playwright) adds setup time (browsers, dependencies).</li><li><strong>Maintenance</strong>: E2E tests are more brittle than unit tests and require maintenance on UI changes.</li></ul>',22)])])}const p=t(n,[["render",i]]);export{u as __pageData,p as default};
